CREATE OR REPLACE FUNCTION public.settle_checkout(_reservation uuid,_method text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.reservations; o public.orders; rid uuid; amount numeric; BEGIN IF auth.uid() IS NULL OR _method NOT IN('Dinheiro','Pix','Cartão de crédito','Cartão de débito','Transferência') THEN RAISE EXCEPTION 'Pagamento inválido'; END IF; SELECT id INTO rid FROM public.cash_registers WHERE user_id=public.account_owner() AND status='aberto' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Abra o caixa antes de receber'; END IF; SELECT * INTO r FROM public.reservations WHERE id=_reservation FOR UPDATE; IF NOT FOUND OR r.user_id<>public.account_owner() OR r.status<>'hospedado' THEN RAISE EXCEPTION 'Estadia inválida'; END IF; amount:=greatest(0,r.total_amount-r.paid_amount); IF amount>0 THEN INSERT INTO public.transactions(user_id,type,category,description,amount,due_date,status,payment_method,business_unit,reservation_id) VALUES(r.user_id,'receita','Hospedagem','Check-out — '||r.guest_name,amount,(now() AT TIME ZONE 'America/Sao_Paulo')::date,'pago',_method,'pousada',r.id); END IF; FOR o IN SELECT * FROM public.orders WHERE reservation_id=r.id AND status='aberta' ORDER BY id FOR UPDATE LOOP UPDATE public.orders SET status='fechada',payment_method=_method,closed_at=now(),cash_register_id=rid WHERE id=o.id; IF o.total>0 THEN INSERT INTO public.transactions(user_id,type,category,description,amount,due_date,status,payment_method,business_unit,order_id,reservation_id) VALUES(r.user_id,'receita','Alimentação','Comanda #'||o.number||' — check-out',o.total,(now() AT TIME ZONE 'America/Sao_Paulo')::date,'pago',_method,'lanchonete',o.id,r.id); END IF; END LOOP; UPDATE public.reservations SET status='finalizada',paid_amount=total_amount WHERE id=r.id; UPDATE public.rooms SET status='limpeza' WHERE id=r.room_id; END $$;